import io.micrometer.tracing.Tracer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class OrderProcessingService {

    private static final Logger log = LoggerFactory.getLogger(OrderProcessingService.class);
    private final Tracer tracer;

    public OrderProcessingService(Tracer tracer) {
        this.tracer = tracer;
    }

    public void processOrder(String orderId) {
        // Manually creating a custom span if business logic warrants granular visibility
        io.micrometer.tracing.Span newSpan = tracer.nextSpan().name("process-order-logic");
        try (Tracer.SpanInScope ws = tracer.withSpan(newSpan.start())) {
            log.info("Processing order with ID: {}", orderId);
            // Simulate business logic
            newSpan.tag("order.id", orderId);
        } finally {
            newSpan.end();
        }
    }
}
